          else (No)
          endswitch
        case (Slow charging is inactive)
          :Switch to state 115;
          :Shut down and exit;
          stop
        endswitch
      else (No)
      endif
    else (No)
    endif

    if (DCDC state is 1?) then (Yes)
      if (No battery pre-heating demand?) then (Yes)
        :Switch to state 95;
        if (Slow charging is inactive?) then (Yes)
          :Shut down and exit;
          stop
        else (No)
        endif
      else (No)
      endif
    else (No)
    endif

    if (Power-up readiness exists?) then (Yes)
      if (Pre-heating demand exists?) then (Yes)
        :Switch to state 115;
        if (Slow charging is inactive?) then (Yes)
          :Shut down and exit;
          stop
        else (No)
        endif
      else (No)
      endif
    else (No)
    endif

    if (Front MCU high-voltage flag is 1?) then (Yes)
      if (Power-up readiness is present?) then (Yes)
        :Switch to state 93;

        switch (What condition is met?)
        case (Vehicle charging/discharging mode is 1 AND Power battery charging demand is 2)
          :Switch to state 95;
          :Switch to state 115;
          if (Slow charging is inactive?) then (Yes)
            :Shut down and exit;
            stop
          else (No)
          endswitch
        case (Charging/discharging power-up guidance is 2 or 3)
          :Switch to state 115;
          if (Slow charging is inactive?) then (Yes)
            :Shut down and exit;
            stop
          else (No)
          endswitch
        case (Vehicle charging/discharging mode is 1)
          :Switch to state 115;
          if (Slow charging is inactive?) then (Yes)
            :Shut down and exit;
            stop
          else (No)
          endswitch
        case (Power battery charging demand is 2)
          :Switch to state 115;
          if (Slow charging is inactive?) then (Yes)
            :Shut down and exit;
            stop
          else (No)
          endswitch
        case (Battery pre-heating demand is 3)
          :Switch to state 115;
          if (Slow charging is inactive?) then (Yes)
            :Shut down and exit;
            stop
          else (No)
          endswitch
        endswitch
      else (No)
      endif
    else (No)
    endif

  else (No)
  endif
else (No)
endif
stop
